import { type ClassValue, clsx } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

"use client";

/**
 * Pagination — custom (Phase 5). Reduced-motion gated page indicator.
 * Active page uses selected-surface + aria-current="page".
 */

import * as React from "react";
import { motion, LayoutGroup, useReducedMotion } from "framer-motion";
import {
  IconChevronLeft,
  IconChevronRight,
  IconChevronsLeft,
  IconChevronsRight,
} from "@tabler/icons-react";
import { cn } from "@/lib/utils";

/* ─── Types ─────────────────────────────────────────────────── */

export type PaginationVariant =
  | "default"
  | "compact"
  | "with-first-last"
  | "load-more";

export type PaginationSize = "sm" | "md";

export interface PaginationProps
  extends Omit<React.HTMLAttributes<HTMLElement>, "onChange"> {
  variant?: PaginationVariant;
  size?: PaginationSize;
  /** Current page (1-indexed). */
  page: number;
  /** Total number of pages. */
  totalPages: number;
  /** Called when the active page changes. */
  onPageChange: (page: number) => void;
  /** Pages shown around the current page (default 1). */
  siblingCount?: number;
  /** Whether a load/fetch operation is in progress (load-more). */
  isLoading?: boolean;
  /** Whether there are more items to load (load-more). */
  hasMore?: boolean;
  /** Callback to load more items (load-more). */
  onLoadMore?: () => void;
  /** Number of items currently loaded (load-more display). */
  loadedCount?: number;
  /** Total number of items (load-more display). */
  totalCount?: number;
}

/* ─── Size maps ─────────────────────────────────────────────── */

const pageButtonSizes: Record<PaginationSize, string> = {
  sm: "size-8 text-xs",
  md: "size-9 text-sm",
};

const navButtonSizes: Record<PaginationSize, string> = {
  sm: "h-8 px-1.5 text-xs [&_svg]:size-3.5",
  md: "h-9 px-2 text-sm [&_svg]:size-4",
};

/* ─── Shared styles ─────────────────────────────────────────── */

const navButtonBase = cn(
  "relative isolate inline-flex shrink-0 items-center justify-center rounded-[var(--primitive-radius-item)]",
  "font-medium leading-none select-none touch-manipulation outline-none",
  "transition-[color,background-color] duration-[150ms] ease-[var(--primitive-ease,cubic-bezier(0.23,1,0.32,1))]",
  "motion-reduce:transition-none",
  "text-[var(--muted-foreground)]",
  "hover:text-[var(--foreground)] hover:bg-[var(--primitive-surface-hover)]",
  "focus-visible:ring-2 focus-visible:ring-[var(--primitive-ring)] focus-visible:ring-offset-2 focus-visible:ring-offset-[var(--background)]",
  "disabled:pointer-events-none disabled:opacity-35",
  "[&_svg]:pointer-events-none [&_svg]:shrink-0",
);

const pageButtonBase = cn(navButtonBase, "tabular-nums");

function LoadingSpinner() {
  return (
    <span
      aria-hidden="true"
      className="size-3.5 shrink-0 rounded-full border-2 border-current border-r-transparent opacity-80 motion-safe:animate-spin"
    />
  );
}

/* ─── Page range calculator ─────────────────────────────────── */

function getPageRange(
  page: number,
  totalPages: number,
  siblingCount: number,
): (number | "ellipsis-start" | "ellipsis-end")[] {
  const totalSlots = siblingCount * 2 + 5;

  if (totalPages <= totalSlots) {
    return Array.from({ length: totalPages }, (_, i) => i + 1);
  }

  const leftSiblingIndex = Math.max(page - siblingCount, 1);
  const rightSiblingIndex = Math.min(page + siblingCount, totalPages);

  const showLeftEllipsis = leftSiblingIndex > 2;
  const showRightEllipsis = rightSiblingIndex < totalPages - 1;

  const items: (number | "ellipsis-start" | "ellipsis-end")[] = [];

  items.push(1);

  if (showLeftEllipsis) {
    items.push("ellipsis-start");
  } else {
    for (let i = 2; i < leftSiblingIndex; i++) items.push(i);
  }

  for (let i = leftSiblingIndex; i <= rightSiblingIndex; i++) {
    if (i !== 1 && i !== totalPages) items.push(i);
  }

  if (showRightEllipsis) {
    items.push("ellipsis-end");
  } else {
    for (let i = rightSiblingIndex + 1; i < totalPages; i++) items.push(i);
  }

  if (totalPages > 1) items.push(totalPages);

  return items;
}

/* ─── <Pagination> ──────────────────────────────────────────── */

export const Pagination = React.forwardRef<HTMLElement, PaginationProps>(
  (
    {
      variant = "default",
      size = "md",
      page,
      totalPages,
      onPageChange,
      siblingCount = 1,
      isLoading = false,
      hasMore = true,
      onLoadMore,
      loadedCount,
      totalCount,
      className,
      ...props
    },
    ref,
  ) => {
    const layoutId = React.useId();
    const reduceMotion = useReducedMotion();
    const indicatorTransition = reduceMotion
      ? { duration: 0 }
      : { type: "spring" as const, duration: 0.26, bounce: 0.08 };

    /* ── Load More variant ─────────────────── */
    if (variant === "load-more") {
      return (
        <nav data-wensity-primitive=""
          ref={ref}
          aria-label="pagination"
          className={cn("flex flex-col items-center gap-3", className)}
          {...props}
        >
          {loadedCount != null && totalCount != null && (
            <p className="text-xs font-medium text-[var(--muted-foreground)] tabular-nums">
              Showing {loadedCount} of {totalCount}
            </p>
          )}
          {hasMore && (
            <button
              type="button"
              disabled={isLoading}
              onClick={() => onLoadMore?.()}
              className={cn(
                "relative h-[var(--primitive-control-height-md)] min-w-[140px] overflow-hidden rounded-[var(--primitive-radius-control)] px-4",
                "text-sm font-medium leading-none",
                "border border-[var(--border-strong)]",
                "bg-[var(--background)] text-[var(--foreground)]",
                "transition-[border-color,background-color] duration-[180ms] ease-[var(--primitive-ease,cubic-bezier(0.23,1,0.32,1))]",
                "motion-reduce:transition-none",
                "hover:border-[color-mix(in_srgb,var(--foreground)_20%,transparent)]",
                "hover:bg-[var(--primitive-surface-hover)]",
                "focus-visible:ring-2 focus-visible:ring-[var(--primitive-ring)] focus-visible:ring-offset-2 focus-visible:ring-offset-[var(--background)]",
                "disabled:opacity-60 disabled:pointer-events-none",
                "outline-none select-none",
              )}
            >
              <span className="relative inline-flex items-center gap-2">
                {isLoading ? <LoadingSpinner /> : null}
                {isLoading ? "Loading…" : "Load more"}
              </span>
            </button>
          )}
        </nav>
      );
    }

    /* ── Compact variant ───────────────────── */
    if (variant === "compact") {
      return (
        <nav
          data-wensity-primitive=""
          ref={ref}
          aria-label="pagination"
          className={cn("flex items-center gap-2", className)}
          {...props}
        >
          <NavArrow
            direction="prev"
            disabled={page <= 1}
            onClick={() => onPageChange(page - 1)}
            size={size}
          />
          <span className="text-sm font-medium tabular-nums text-[var(--muted-foreground)] select-none px-1">
            <span className="text-[var(--foreground)]">{page}</span>
            <span className="mx-1 opacity-40">/</span>
            {totalPages}
          </span>
          <NavArrow
            direction="next"
            disabled={page >= totalPages}
            onClick={() => onPageChange(page + 1)}
            size={size}
          />
        </nav>
      );
    }

    /* ── Default & With First/Last ─────────── */
    const showFirstLast = variant === "with-first-last";
    const pages = getPageRange(page, totalPages, siblingCount);

    return (
      <nav
        data-wensity-primitive=""
        ref={ref}
        aria-label="pagination"
        className={cn(
          "inline-flex w-full max-w-[360px] items-center justify-between gap-4",
          "rounded-[var(--primitive-radius-surface)] p-1",
          "border border-[var(--border)] bg-[var(--primitive-surface-hover)]",
          className,
        )}
        {...props}
      >
        <div className="flex shrink-0 items-center gap-1">
          {showFirstLast && (
            <NavArrow
              direction="first"
              disabled={page <= 1}
              onClick={() => onPageChange(1)}
              size={size}
            />
          )}
          <NavArrow
            direction="prev"
            disabled={page <= 1}
            onClick={() => onPageChange(page - 1)}
            size={size}
          />
        </div>

        <LayoutGroup id={layoutId}>
          <div className="mx-1 flex min-w-0 flex-1 items-center justify-center gap-0.5">
            {pages.map((item) => {
              if (item === "ellipsis-start" || item === "ellipsis-end") {
                return (
                  <span
                    key={item}
                    className={cn(
                      "inline-flex select-none items-center justify-center text-[var(--muted-foreground)] opacity-50",
                      pageButtonSizes[size],
                    )}
                  >
                    ⋯
                  </span>
                );
              }
              const isActive = item === page;
              return (
                <button
                  key={item}
                  type="button"
                  aria-label={`Page ${item}`}
                  aria-current={isActive ? "page" : undefined}
                  onClick={() => onPageChange(item)}
                  className={cn(
                    pageButtonBase,
                    pageButtonSizes[size],
                    isActive
                      ? "text-[var(--foreground)]"
                      : "text-[var(--muted-foreground)]",
                  )}
                >
                  {isActive ? (
                    <motion.span
                      layoutId={`page-active-${layoutId}`}
                      className={cn(
                        "absolute inset-0 rounded-[var(--primitive-radius-item)]",
                        "border border-[var(--border)] bg-[var(--primitive-surface-selected)]",
                      )}
                      transition={indicatorTransition}
                      style={{ zIndex: -1 }}
                    />
                  ) : null}
                  <span className="relative z-[1]">{item}</span>
                </button>
              );
            })}
          </div>
        </LayoutGroup>

        <div className="flex shrink-0 items-center gap-1">
          <NavArrow
            direction="next"
            disabled={page >= totalPages}
            onClick={() => onPageChange(page + 1)}
            size={size}
          />
          {showFirstLast && (
            <NavArrow
              direction="last"
              disabled={page >= totalPages}
              onClick={() => onPageChange(totalPages)}
              size={size}
            />
          )}
        </div>
      </nav>
    );
  },
);
Pagination.displayName = "Pagination";

/* ─── Nav arrow button ──────────────────────────────────────── */

function NavArrow({
  direction,
  disabled,
  onClick,
  size,
}: {
  direction: "first" | "prev" | "next" | "last";
  disabled: boolean;
  onClick: () => void;
  size: PaginationSize;
}) {
  const labels: Record<string, string> = {
    first: "First page",
    prev: "Previous page",
    next: "Next page",
    last: "Last page",
  };

  const icons: Record<string, React.ReactNode> = {
    first: <IconChevronsLeft />,
    prev: <IconChevronLeft />,
    next: <IconChevronRight />,
    last: <IconChevronsRight />,
  };

  return (
    <button
      type="button"
      aria-label={labels[direction]}
      disabled={disabled}
      onClick={onClick}
      className={cn(navButtonBase, navButtonSizes[size])}
    >
      {icons[direction]}
    </button>
  );
}
